import{_ as t,o as e,c as a,Q as n}from"./chunks/framework.b67c47e6.js";const m=JSON.parse('{"title":"Company Backup","description":"","frontmatter":{},"headers":[],"relativePath":"guide/management/backup/index.md","filePath":"guide/management/backup/index.md","lastUpdated":1790346505000}'),o={name:"guide/management/backup/index.md"},s=n('<h1 id="company-backup" tabindex="-1">Company Backup <a class="header-anchor" href="#company-backup" aria-label="Permalink to &quot;Company Backup&quot;">​</a></h1><p>The backup feature lets company admins generate a full export of their company data for safekeeping.</p><h2 id="generating-a-backup" tabindex="-1">Generating a Backup <a class="header-anchor" href="#generating-a-backup" aria-label="Permalink to &quot;Generating a Backup&quot;">​</a></h2><ol><li>Go to <strong>Company settings</strong> (in the <strong>Settings</strong> section of the left menu, in company-wide mode).</li><li>On the company card, click <strong>Company Backups</strong>. Only company admins see this button.</li><li>Check the <strong>email</strong> address the download link is sent to. It is filled in with your own.</li><li>Choose what to include: <strong>Include company data</strong>, <strong>Include users data</strong> and <strong>Include production lines data</strong> are all ticked by default.</li><li>Pick the projects in <strong>Select projects to include in backup</strong>, or use the shortcut buttons: <strong>ADD STDLIBS</strong> (standard libraries), <strong>ADD PROJECTS</strong> (active projects), <strong>ADD ARCHIVED</strong> (archived projects), <strong>ADD ALL</strong>, and <strong>Clean</strong> to empty the list.</li><li>Click <strong>Generate</strong>.</li></ol><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Backups are generated in the background and can take some time, depending on the amount of data. When the backup is ready, you get an email with the download link, and the same link arrives as a message in the app.</p></div><h2 id="what-s-included" tabindex="-1">What&#39;s Included <a class="header-anchor" href="#what-s-included" aria-label="Permalink to &quot;What&#39;s Included&quot;">​</a></h2><p>The backup is a single <code>.zip</code> file. Depending on what you ticked, it contains:</p><ul><li><strong>Company data</strong>: the company record and its files (logos, banners), production events, company-level reports, webhooks, parsing setups, and the part batches and proofs that belong to no project.</li><li><strong>Users data</strong>: the user accounts of the company.</li><li><strong>Production lines data</strong>: production lines, stations, machine setups, action triggers and their setups, with their files (such as checklist docs).</li><li><strong>Each selected project</strong>: the project and its files, batches, designs, constructibles and parts with their files, issues, production proofs, part batches and reports.</li></ul>',8),i=[s];function r(c,d,l,p,u,h){return e(),a("div",null,i)}const k=t(o,[["render",r]]);export{m as __pageData,k as default};
